data = json.loads(GUIDE.read_text(encoding="utf-8"))
pages = data["pages"]
changed = 0
for page, slots in FIXES.items():
    if page not in pages:
        raise SystemExit(f"Missing guide page: {page}")
    for index, value in slots.items():
        if index >= len(pages[page]):
            raise SystemExit(f"Missing guide slot {page}[{index}]")
        if pages[page][index] != value:
            pages[page][index] = value
            changed += 1
GUIDE.write_text(json.dumps(data, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")
print(f"Applied {changed} factual ru_ru guide corrections")
